export function dfs(adj: Record<string, string[]>, s: string): string[] {
	const order: string[] = [];
	const seen = new Set<string>();
	function visit(u: string) {
		seen.add(u);
		for (const v of adj[u] || []) if (!seen.has(v)) visit(v);
		order.push(u); // postorder
	}
	visit(s);
	return order;
}

export function kadane(a: number[]): number {
	let best = -Infinity;
	let cur = 0;
	for (const x of a) {
		cur = Math.max(x, cur + x);
		best = Math.max(best, cur);
	}
	return best;
}

export function fib(n: number): number {
	if (n <= 1) return n;
	let a = 0, b = 1;
	for (let i = 2; i <= n; i++) {
		const c = a + b;
		a = b;
		b = c;
	}
	return b;
}
